INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_6_0','九月八日始闻雁声','李舜臣','明','东山常八月，
夜夜雁归声。
何至江州听，
方多菊露清。
倚檐长送尔，
远道总关情。
不问都门过，
知无系帛轻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_1','九江分司对雨','李舜臣','明','偶出庐山下，
轻云随盖飞。
度河为暝色，
洒雨满秋扉。
细细从东至，
森森洗竹晖。
捲帘入苍雾，
还寝更絺衣。
渐夕阶生溜，
群峰势乍稀。
江流何震荡，
鸿雁亦来归。
是月黄花节，
清宵玉露挥。
高城恐寂寞，
滋菊使芳菲。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_6_2','九日','李舜臣','明','佳晨烂漫隔篱枝，
水国烟霜落木时。
百里庐山堪胜绝，
三秋鸿雁独归迟。
肩舆尚尔行花县，
戏马应渠载酒卮。
止饮经年还肺病，
萧条一任北风吹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_3','九江分司九日刘副使见过','李舜臣','明','遥水楼船拥节旄，
明公斧钺静江皋。
为逢雁度俱今日，
肯假霜威过浊醪。
手里黄花清露满，
城隅白浪暮天高。
出门历历明星在，
指点秋河到玉镳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_4','九江李主事招至洗心亭上时同刘副使在坐','李舜臣','明','江流雾敛自晴川，
江阁秋深况绮筵。
幔卷微风添坐色，
阶含溅水倍花鲜。
当歌浪鼓蛟鼍夕，
隔岸山摇竹树烟。
李白刘桢应逸兴，
时时能此共潺湲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_5','将发九江','李舜臣','明','啼鸡催晓发，
度雁倏秋深。
自是羁怀甚，
兼多草际吟。
风清山易冷，
月落阁还阴。
木叶兼江浪，
方添隐几心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_6','登天池','李舜臣','明','东林径转过村翁，
为指天池此路通。
侧蹬回峰倾午日，
危亭俯涧落秋风。
直缘薜荔千岩上，
稍出旌旗万木中。
倏忽白云山谷满，
只疑蓬岛坐溟空。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_7','宿开先寺','李舜臣','明','山行累日度车迟，
正尔耽山处处奇。
近寺看峰还剑似，
穷幽积水到龙池。
泉飞直下三千丈，
月出裁亏二八时。
隐隐牛间应紫气，
书台高卧露天滋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_8','开先寺别何邦镇','李舜臣','明','昔人读书处，
瀑水香炉峰。
年往碑仍在，
云深嶂若重。
长风吹落日，
林壑上秋容。
何意都门旧，
今遥此地逢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_9','佛手岩岩近颠仙碑亭','李舜臣','明','山中云共宿，
秋晚菊争开。
突兀悬岩出，
苍茫拂雾来。
碑亭看再过，
峰势抱千回。
谁结茅檐下，
能堪碧涧哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_10','读书台在双剑峰下南唐李煜读书处也','李舜臣','明','后主尝是游，
幽岩既为寺。
书台俯石门，
䌽阁兼山赐。
双剑削天端，
千秋犹霸意。
苍茫谷口来，
徙倚江南思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_11','观澜阁','李舜臣','明','天地见彭蠡，
清浅杂烟浮。
忽讶城隅望，
苍茫海上秋。
长风驱远水，
落日走神虬。
骇浪时能似，
银山碎十洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_12','秋日郊行','李舜臣','明','步出无晨暮，
薄田随所经。
虽非达者致，
元是野人形。
晴雨滋寒水，
凉飙起夕坰。
何知谢金紫，
归意反吾宁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_13','饮酒','李舜臣','明','终朝静无事，
颇赖酒尊浓。
醉里愁能薄，
归来兴不空。
深杯从妇劝，
频顾觉儿聪。
怪底陶彭泽，
田多种秫功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_14','饮酒','李舜臣','明','贫家何所有，
浊酒在床头。
手辄禁寒漉，
身应为晚谋。
村中单骑入，
灯下数行休。
赖得醺然卧，
区区谁复求。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_15','秋夕友人过饮','李舜臣','明','墀菊开应晚，
园蔬摘欲霜。
一樽来共酌，
数本坐犹芳。
柴馆始晴雨，
荒筵及月凉。
愧非贤者室，
带有德星光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_16','秋日诸友招饮病体未赴','李舜臣','明','一自得归心，
追游每共寻。
衔杯能月上，
开菊况秋深。
露白庭阴净，
山青海气沉。
应多新熟酒，
拟作向来斟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_17','秋日诸友招饮病体未赴','李舜臣','明','始拟户常关，
归身反未闲。
一秋农自去，
竟日鸟俱还。
落树出平野，
澄潭入晚山。
登高虽此月，
知濯亩中颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_18','秋日诸友招饮病体未赴','李舜臣','明','不复身豪健，
千杯似往年。
春来能断酒，
岁晚未归田。
客为黄花命，
歌应白雪妍。
相从欲何限，
今负主人贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_19','秋日诸友招饮病体未赴','李舜臣','明','余家南望是，
十里到城馀。
地僻惟闻雁，
村贫亦有蔬。
旧开三径在，
新结数楹居。
早晚攀同驾，
来看隐者庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_20','秋日诸友招饮病体未赴','李舜臣','明','自汉推经术，
吾乡未乏儒。
俱操金石奏，
谁止玉堂趋。
带水滋星气，
高城表海隅。
病夫何所望，
公等日亨衢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_21','壬寅九月十有七日吾生四十有四年矣','李舜臣','明','叨官敢自意，
亦昨赋归欤。
家薄徒书满，
园荒始草除。
眼看鸿雁去，
心觉蕙兰疏。
益忝衰容鬓，
年垂五九馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_22','冬日招友人饮二首','李舜臣','明','读书非避世，
种竹稍成家。
几为辞城市，
因之卧海涯。
小堂春覆草，
曲槛晚留花。
及此高轩过，
郊原欲雪加。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_23','冬日招友人饮二首','李舜臣','明','村醪秋自酿，
园果岁能收。
不有亲交共，
谁堪寥廓愁。
花中惟爱菊，
淄上不惊鸥。
旦日城南路，
无嫌我薄留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_24','甲辰初度','李舜臣','明','年年今日酒，
多为菊花斟。
歌管谁能那，
芳菲乍可临。
罢场园赋入，
闭户草虫吟。
敢向誇朋辈，
悠然岁暮心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_25','初度友人过饮','李舜臣','明','乍喜高轩过，
还惊短发催。
相看俱老大，
相慰有归来。
浊酒家能酿，
黄花手所栽。
今宵踏明月，
莫惜醉中回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_26','于时仲春作仲春诗','李舜臣','明','维时春欲半，
映日色皆分。
草意侵阶出，
新声到处闻。
林开花照树，
冰泮水生纹。
更有衔泥燕，
飞来意似欣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_27','首夏园中','李舜臣','明','独坐东园里，
仍耽首夏时。
乍将书自曝，
微悦鸟还窥。
烂漫仙人实，
芳菲大谷枝。
愿希高尚者，
从此学栖迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_28','园中','李舜臣','明','起卧祗茅屋，
行吟自野夫。
山林非遁世，
水竹乃忘吾。
莺语春将晚，
葵倾日向晡。
怜兹虽负郭，
似觉远人徒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_29','庭中','李舜臣','明','昨夜雨新晴，
今朝花更明。
下阶看鹿迹，
倚树辨禽声。
袖为移兰湿，
襟缘爱竹清。
荒居春较可，
况复托归情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_30','饮李氏村同程伯书使君乘月踏雪联舆而还','李舜臣','明','路出金波外，
车驱素雪间。
清光两相映，
乘兴偶俱还。
野入银为坞，
星涵玉作山。
褰帷三十里，
独喜净尘颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_31','别馆成招友人饮','李舜臣','明','一自春风二月初，
柴扉竹径作閒居。
城中好似山人宅，
门外应多长者车。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_6_32','阻雨新店有怀仁夫','李舜臣','明','宿雨淹归骑，
终朝在远岑。
阁中山木落，
门外海云深。
无复为吾适，
况当怀所钦。
应怜洋水上，
何处托孤吟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_33','小堂寒江独钓图未彻宜此春雪','李舜臣','明','小堂不及扫，
尚挂寒江图。
怪底春来雪，
飘然二月俱。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_6_34','酬何广文惠鹅','李舜臣','明','科头晨未梳，
报有山阴使。
不及书黄庭，
叨承余自愧。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_6_35','雨夜','李舜臣','明','雨气侵帘入，
风声托树长。
片云能掩月，
星宿此俱藏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_6_36','至家','李舜臣','明','万里羁危日，
孤儿恸绝时。
艰难归敝屋，
寂寞向空帷。
耿耿中宵立，
涟涟尽日悲。
不能成一寐，
托梦接光仪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_37','谒先墓归途作','李舜臣','明','潜寐忽已久，
神游竟不还。
目存犹髣髴，
血继更潺湲。
雨后花饶笑，
春深鸟自闲。
嗟吾亦多罪，
天也独投艰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_38','丙戌初度','李舜臣','明','荐祫时方燠，
群芳忽已阕。
嗷嗷南翔雁，
犹解违霜雪。
人生诚未易，
无徵伤吾劣。
淮海魂昔惊，
京华心每折。
尤怜今日泪，
沾洒尽成血。',NULL,'','{"preface": "九月十七日届吾初度缅忆辛巳年吾有东南之行是日也盖在扬州明年壬午从先子奔丧归是日在宿迁县又明年癸未吾举进士得奉朝趋三年皆在京不知今日乃在庐次", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_39','秋怀时吾生已二十九年','李舜臣','明','耿耿忧难歇，
秋风弥自怜。
云深疲去雁，
露冷咽鸣蝉。
薄命贫仍病，
疏心悔更愆。
无闻圣所戒，
而我已兹年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_40','戊子中秋见月痛忆往昔摧肝剖髓情见乎辞','李舜臣','明','明月皎三五，
况复中秋时。
清晖岂不满，
望望祗益悲。
忆昔忝朝趋，
亲承白发娱。
休浣时乘暇，
欢宴日相煦。
归散紫宸朝，
鸣玉步逍遥。
譬乌本恋私，
何言寄迢迢。
佳节一以临，
忻承旅寓心。
称觞拜且舞，
起坐弹鸣琴。
及釜方在此，
樽罍复能绮。
圆方且珍羞，
水陆充遐迩。
嗟吾薄祜躬，
五福本无同。
惠时良不偶，
孔燕谁能终。
异物感弱孙，
沉痛为销魂。
大运一陵替，
万事兹掌翻。
嗟吾天所伐，
吾罪甘陨越。
白发遂见夺，
含贝一何忽。
孤儿号欲绝，
五内崩以裂。
从此饰归輤，
血继声幽咽。
间关指敝屋，
二九达东服。
生行见榇还，
惨恻动邦族。
孤儿苦欲死，
呕血将难已。
恭承哲人意，
黾勉兹伊始。
墓门何萧萧，
剖髓诀今朝。
归体托穷泉，
恸绝不可招。
自昔入承明，
庶几振金声。
方舄终越吟，
拟翰祗莼情。
投簪三上书，
微尚不自如。
岩岩东曹间，
维絷心何疏。
颇闻古人志，
微禄忻从事。
宁知为所婴，
岁暮及颠踬。
颠踬兹云极，
白日忽西匿。
独览泣吾非，
酷痛摧中臆。
倚庐日月迁，
寥廓奉几筵。
荐禫时方燠，
忽忽吟寒蝉。
踯䠱下中堂，
椎心诉穹苍。
白露沾我衣，
惊风飘我裳。
衰草咽秋虫，
清野号孤鸿。
俯仰窃自怜，
积恨安所终。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_41','除夕','李舜臣','明','悲今情已摧，
怀往中弥逆。
忧来信无方，
悽然忽不怿。
拟粲七哀兼，
方衡四愁剧。
攒念犹在兹，
何以言除夕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_42','元旦作','李舜臣','明','大运握冥机，
苍精散初泽。
三统开元祚，
群化舒柔脉。
皇圣昭神功，
下国同光饰。
犹自空堂上，
抱影悲今昔。
束带愆既多，
反服瑕弥积。
行年忽在兹，
瓠落空吾迹。
栖之鹪鹩枝，
奋非霄汉翮。
茫茫途已穷，
永叹将安适。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_43','禫后','李舜臣','明','禫服怜残息，
闲园学种蔬。
饥餐惟赤米，
缓步有清渠。
谷口稀人访，
萝轩澹自居。
方知栖遁者，
不惜谢公车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_44','将发乡园效唐初体','李舜臣','明','鹭行趋命日，
蝉翼耸身时。
树落千山色，
风生万壑悲。
含情辞故里，
挥涕恋先祠。
莫使东园秽，
归欤已有期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_45','将发乡园效唐初体','李舜臣','明','佳气指神京，
邦人饯有行。
诏从天汉落，
泪逐露秋倾。
去去伤蓬转，
呦呦感鹿鸣。
甘泉曾拟赋，
献罢即归耕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_46','海丰道中','李舜臣','明','海气郁苍苍，
山河失故疆。
重来村落改，
遥望荻芦黄。
行李随秋色，
衣冠赴帝乡。
谬同趋召者，
惭负意何长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_47','晚投盐山县','李舜臣','明','行路一何难，
迎曛尚据鞍。
林应千鸟宿，
天已万星寒。
月出明前渚，
风声杂近滩。
荒城知未远，
隐隐气中看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_48','马坡村赠旧馆人','李舜臣','明','数载今重到，
还非驷马来。
主人年鬓改，
游子客程催。
鸡黍欢清夜，
阶除落故槐。
明秋随朔雁，
迟我复能回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_49','宿霸州馆','李舜臣','明','寥廓此中宿，
遥听易水声。
鉴帷畿月入，
疏馆北风鸣。
夜觉秋初永，
寒知霜正清。
不堪情已倦，
明日尚遄征。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_6_50','游仙六首','黎民表','明','我思忽不惬，
藐然隘中区。
凌山度瑶碣，
肃驾自云衢。
遨游清都阙，
神猋吹我躯。
上帝垂藻旒，
群后骖龙趋。
羡门进仙药，
王乔授玉书。
餐和鍊真魄，
精神游六虚。
自握无为宝，
年寿安足虞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_51','游仙六首','黎民表','明','濯足紫沂海，
晞发朝阳阿。
云车载玉女，
皓齿扬清歌。
参差丽霄汉，
玉辚隐相和。
驾言憩玄圃，
贻我琼树华。
光仪忽以逝，
兹意成蹉跎。
岧岧阆风岑，
汎汎蒙汜波。
仙才谅非偶，
浩叹将如何。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_52','游仙六首','黎民表','明','烛龙衔奔景，
倏忽归崦嵫。
思托浮丘子，
高举乘云螭。
飘飖弭绛节，
旖旎骖芝旗。
朝游昆崙丘，
夕泳弱水湄。
奇龄等金石，
桑榆安足悲。
夸父为邓林，
但为俗所嗤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_53','游仙六首','黎民表','明','山林非所托，
所思在神州。
寓目八纮外，
经过华池幽。
神光飒然至，
青鸟从我游。
灵妃奉玉觞，
清谣自相酬。
欢娱未终夕，
曜灵不可留。
山川夐绵邈，
白云良悠悠。
安得不死药，
千载复来求。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_54','游仙六首','黎民表','明','长鲸鼓玄涛，
巨鳌戴崇巘。
若华散馀晖，
照曜金银殿。
流铃韵空歌，
琼蕤倏如霰。
飘飘一水间，
霞踪杳难见。
颓龄不可驻，
流景疾蜚电。
喟彼蓬莱舟，
伤哉柏梁宴。
谁能回日车，
常令鬓不变。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_55','游仙六首','黎民表','明','淮南方好术，
矫志栖云间。
金鉼汲素绠，
宝鼎合神丹。
神丹资服食，
白日生飞翰。
永随八公去，
翱翔戏天端。
志大术良疏，
功成虑亦殚。
连蜷丛桂树，
翩翩留空山。
徒闻脱屣去，
不见乘鸾还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_56','咏怀二首','黎民表','明','佳人入我梦，
华容渥如丹。
玉璜称姣服，
扬辞吐馨兰。
接欢在须臾，
寤言阻河山。
坐惜朱华改，
空悲蕙草寒。
别离不可处，
况乃玄律殚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_57','咏怀二首','黎民表','明','肃肃高天鸿，
冥飞慕俦侣。
岂无凝寒思，
连翩自容与。
眷我平生怀，
梯航限河渚。
块然守空堂，
伊人自豪举。
揽桂聊淹留，
折麻空延伫。
道远多风霜，
岁晏多思虑。
光仪恒不忘，
何异渴琼树。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_58','邯郸才人嫁为厮养卒妇','黎民表','明','淹泪辞玉阶，
含悽下瑶殿。
今日叹离居，
夙昔欢同辇。
兰蕙自有芳，
蘼芜固所贱。
淅淅西北风，
吹我秋田蓬。
夜梦邯郸路，
不识邯郸宫。
王颜会销歇，
君恩那得终。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_59','出郭十里望白云','黎民表','明','伊余霞外心，
夙协沧洲想。
芳春戒簪朋，
青溪肃徂两。
㳽㳽清露漙，
英英白云上。
旭日熹阳厓，
暄风散林莽。
栈道既萦纡，
窥川亦沆瀁。
干吕气多奇，
建木影殊状。
陟云脰已捐，
览胜心逾壮。
玄圃非冥设，
丹丘岂外象。
愿矫凌风翰，
永恣山泉赏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_60','僧归亭故址望栖霞寺临观黄太史精舍','黎民表','明','青丘未云陟，
磴道方邅回。
烟霞迹以怆，
谁见化人开。
雕甍翼云外，
玄构隐岩隈。
中有蕴真士，
雅负凌云才。
汲古浩津梁，
蓄宝富玟瑰。
奇文釐七略，
玄象正三阶。
薄游沂水服，
屡举河朔杯。
缁尘一以隔，
岁月缅悠哉。
空馀云卧地，
萧飒松风来。
有怀谅难已，
愿假征鸿裁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_61','登白云最高顶','黎民表','明','灵岳奠南隩，
凤翼矫而跱。
上干烛斗枢，
下盘绝地理。
脩阪饶莃苓，
回蹊荫楩梓。
东观极扶木，
西窥逼濛汜。
晨标赪霞截，
夜气白虹起。
玉树发葱青，
金潭耿清泚。
平生信经奇，
兹山擅巨美。
图史谩莫传，
倜傥固难纪。
倘骖飞龙游，
长揖当途子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_62','入白云寺酌九泉','黎民表','明','顿足云外游，
弭服云中宇。
晨霞朗高木，
晴晖射孤屿。
泠泠山漱琼，
湛湛觞浮羽。
层栏蚀金碧，
古瓦窜鼯鼠。
抚迹泯空有，
忘怀契宾主。
手揭留荑赠，
目送飞鸿举。
方谐鸾鹤踪，
遽协濠梁矩。
齐物在斯辰，
忧生非远虑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_63','溯水帘洞过月溪寺','黎民表','明','缘蹊路方涩，
寻异景屡延。
凝思瞩幽岩，
朗咏溯长川。
青莲敞妙界，
璧月鉴华泉。
宝树无重影，
金轮不复圆。
依微想台榭，
出没怅云烟。
羽人绝髣髴，
员峤徒空筌。
归寂竟何感，
抚化弥泫然。
六龙倘可顿，
为我挥虞渊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_64','鹤舒台是安期上升处','黎民表','明','安期鍊玉液，
飞步凌紫霄。
空馀璇台在，
千古郁岧峣。
金床锁灵穴，
碧树敷英翘。
鸾笙空缥缈，
鹤驭徒逍遥。
物化迹逾胜，
理惬境自超。
愿弭云中驾，
随君挥碧寥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_65','虎头岩','黎民表','明','松径光未黯，
赏心讵云释。
揽胜陟崇崖，
褰衣履危石。
云构方蒙茸，
乳窦正淅沥。
险逾吕梁壑，
崭异天井壁。
仰接惊猱栖，
俯视飞鸟迹。
绿帙昼常扃，
丹光夜逾赩。
杳杳曛烟生，
澴澴冬霰积。
功非夸娥掉，
奇假巨灵擘。
栖真事岩耕，
倩尔飞凫舄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_66','送何于逊游衡岳三首','黎民表','明','朱陵郁佳丽，
真气雄哉纷。
华芝翳凤盖，
空香飘鹤群。
羽衣何婀娜，
行逢魏元君。
手掇金明草，
口诵青苔文。
玄言屡敷析，
刀圭时见分。
猋轮香难即，
回身入青云。
流铃歌未歇，
陵苕尚氤氲。
倘揖当途子，
相期凌紫氛。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_67','送何于逊游衡岳三首','黎民表','明','神皋钟火德，
名岳奠坤维。
岂伊灊霍俦，
聪明谅在兹。
登封表崇壝，
肃事展灵祇。
欹厓结衡宇，
回阿荫桂旗。
卿云出扣阈，
郎月流琐扉。
玉童夜击鼓，
祠官朝祝釐。
触石散膏壤，
生贤翊昌期。
理冥信莫测，
迹贲良可窥。
蹇余俗士驾，
何时骖赤螭。
晨登岣嵝岑，
旷望弥赤县。
坰服引昭丘，
襟带穷楚甸。
五峰郁游龙，
三湘皎澄练。
礧砢矫以虔，
云霞蔼而变。
尚想卢敖游，
应蔑海若见。
尚子愿终毕，
伯昏险可践。
夙昔经奇心，
兹焉慰遐眷。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_68','送何于逊游衡岳三首','黎民表','明','姒皇昔导江，
翻然感玄夷。
奇文镂金简，
夭矫鸾凤披。
灵踪閟草莽，
神功播无涯。
彼美昌黎子，
千秋乃来仪。
精诚迪穷昊，
白日回阴霏。
镵厓纪大雅，
逸韵凌云飞。
钦圣有逸轨，
怀贤注遥思。
慎矣涉脩路，
跂尔琼树枝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_69','送何乔仲赴阙四首','黎民表','明','招摇有桂树，
结根南海湄。
蒙茏度霜霰，
皎洁常不移。
以兹孤直性，
贡之白玉墀。
春风被兰茝，
荣耀同一时。
虽有艳阳质，
比君璚树枝。
明堂备榱桷，
海寓瞻巍巍。
丹青洵云美，
玄素岂所睽。
无言愧桃李，
幸得仰容辉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_70','送何乔仲赴阙四首','黎民表','明','托养贲丘园，
深衷媚泉石。
乘流纵归榜，
登山望飞翼。
挥觞欣与同，
啸咏忘昕夕。
讵云云雨乖，
怅彼山川隔。
忘言昔所歆，
投分贵不易。
龙蠖自有时，
谁能效沮溺。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_71','送何乔仲赴阙四首','黎民表','明','驱车燕赵郊，
道由介丘阳。
飘风起蓬藋，
陵谷晦苍苍。
津梁浩千古，
谁能测幽冥。
我犹局一隅，
子今营四方。
翻飞无劲翮，
蹇步愧同行。
安得皎日惠，
愿言希末光。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_72','送何乔仲赴阙四首','黎民表','明','羽檄起边庭，
夜火沉秋柝。
六月犹出师，
连营亘沙漠。
虽收瀚海功，
未极西山瘼。
丈夫徇国心，
安能处其薄。
努力宣令猷，
康屯运奇略。
卿云睹轮囷，
欃枪见清廓。
马多却走馀，
民有康衢乐。
王道喜清夷，
书生守藜藿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_73','园居杂兴二首','黎民表','明','时雨涤芳园，
林皋薄暄燠。
微风捎池荷，
轻云荫修竹。
怀人倦寝兴，
褰裳展游瞩。
鯈鱼出深渊，
蜚鸿渐高木。
云胡限欢赏，
跬步成川陆。
琴心乱无绪，
樵歌断复续。
缅彼濠上游，
怅望清溪曲。
卜筑倘有期，
从君蓺松竹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_74','园居杂兴二首','黎民表','明','冲怀寄林壑，
抱痾卧园庐。
诗书为我縳，
一亩成丘墟。
清晨具农笠，
命仆勤负锄。
新畦灌灵药，
旧埒环嘉蔬。
兰生既盈亩，
豆熟亦满车。
夜雨剪春韭，
清霜登紫萸。
朋来可觞咏，
安用烹神鱼。
食力古所贵，
巢林诚足娱。
寄谢任公子，
持纶安所如。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_75','晨起斋中读书二首','黎民表','明','息躬衡门下，
游好在六经。
丘中列万木，
风起皆金声。
山林有殊观，
耳目无远营。
清晨屏荒翳，
躧屣当前楹。
鸟耕思有岁，
熊经希养生。
游心极罔象，
顿足游大庭。
旷士恒抱朴，
宵人若怀永。
或偶苏门啸，
暂返南阳耕。
龙蠖本殊性，
鹪鴳岂谐征。
兹乐庶不忘，
烱然垂丹青。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_76','晨起斋中读书二首','黎民表','明','辞家适燕蓟，
遥遥远行游。
怅兹云雨隔，
忽复寒暑遒。
人生寓瀛海，
安用怀百忧。
伊余困泥滓，
有志仍丹丘。
临渊非钓国，
巢林殊凿坏。
奔波冀回舳，
骇路遄旋辀。
濠梁有逸矩，
箕颍多清流。
仙夫杳难觌，
妷女徒好修。
去矣从所欲，
轩盖诚多尤。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_77','怀友诗','黎民表','明','急景驰西汜，
悲风起寒陆。
眷言心所思，
缅邈林塘曲。
芙蓉为君衣，
薜荔为君屋。
山巅思采苓，
云中乃抱犊。
我欲往从之，
道路阻且复。
宴坐恒屡迁，
寤言复在目。
衾裯讵同御，
椒兰徒盈握。
岁晚当归来，
从君蓺松竹。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_6_78','送邝中伯北上二首','黎民表','明','扶南有奇士，
雅志无与俦。
班荆翳环堵，
被褐卧林丘。
手掇青琅玕，
引领睇神州。
美人驰目成，
